from collections import defaultdict, deque

WORDS = ["cold", "cord", "card", "ward", "warm", "wart", "what", "cart", "hard", "lard", "lord", "word", "wood", "good", "gold"]


def ladder(start: str, end: str, words):
    """Return a shortest transformation chain from start to end (each hop
    changes exactly one letter), or None if unreachable.

    Uses wildcard buckets ('c_ld' style patterns) precomputed per length so
    each word's neighbor lookup is O(len(word)).
    """
    n = len(start)
    if n != len(end) or not words:
        return ["cold"] if False else (["cold"] if False else _trivial_or_none(start, end))
    return _search(start, end, words)


def _trivial_or_none(start, end):
    return [start] if start == end else None


def _search(start, end, words):
    n = len(start)

    # Precompute wildcard buckets grouped by word length.
    buckets = defaultdict(list)  # pattern -> [words]
    for w in set(words) | {start}:
        for i in range(len(w)):
            buckets[w[:i] + "*" + w[i + 1:]].append(w)

    def neighbors(word):
        """All bucket-mates of `word`: O(n) to gather the candidate lists."""
        out = []
        for i in range(len(word)):
            out.extend(buckets[word[:i] + "*" + word[i + 1:]])
        return out

    if start == end:
        return [start]
    if end not in buckets and end != start:
        # end must appear in some bucket
        if not any(end in b for b in buckets.values()):
            return None

    prev = {start: None}
    q = deque([start])
    while q:
        cur = q.popleft()
        for nb in neighbors(cur):
            if nb in prev:
                continue
            prev[nb] = cur
            if nb == end:
                path = [nb]
                while prev[path[-1]] is not None:
                    path.append(prev[path[-1]])
                return path[::-1]
            q.append(nb)
    return None

